import { _decorator, Component, EventMouse, EventTouch, Input, input } from 'cc';
import type { Bus } from '../../Engine/Bus';
import { HallEvents } from '../HallEvents';
import { GameData } from '../../Core/Data/GameData';
import { worldToGrid } from '../Config/GridConfig';

const { ccclass } = _decorator;

@ccclass('HallInputSystem')
export class HallInputSystem extends Component {

    private _bus: Bus = null!;

    setup(bus: Bus): void {
        this._bus = bus;
    }

    onEnable() {
        input.on(Input.EventType.TOUCH_END, this._onTouchEnd, this);
        input.on(Input.EventType.MOUSE_UP, this._onMouseUp, this);
    }

    onDisable() {
        input.off(Input.EventType.TOUCH_END, this._onTouchEnd, this);
        input.off(Input.EventType.MOUSE_UP, this._onMouseUp, this);
    }

    private _onTouchEnd(e: EventTouch): void {
        const p = e.getUILocation();
        this._emitClick(p.x, p.y);
    }

    private _onMouseUp(e: EventMouse): void {
        if (e.getButton() !== EventMouse.BUTTON_LEFT) return;
        const p = e.getUILocation();
        this._emitClick(p.x, p.y);
    }

    private _emitClick(uiX: number, uiY: number): void {
        if (!this._bus) return;
        // UI 坐标（左下原点）→ 世界坐标（屏幕中心原点）
        const wx = uiX - GameData.viewW / 2;
        const wy = uiY - GameData.viewH / 2;

        const grid = worldToGrid(wx, wy);
        if (!grid) return;           // 点在网格外，忽略

        this._bus.emit(HallEvents.CLICK_GRID, grid);
    }
}